/* selectMasterMdCtBuyerGroupManageList */ SELECT A.GROUP_CODE ,A.GROUP_NAME ,A.ADD_USER_ID ,A.ADD_DATE ,A.USE_FLAG ,A.SORT_SEQ ,(SELECT COUNT(*) FROM BNTBUYERGROUP B WHERE A.GROUP_CODE = B.GROUP_CODE AND GROUP_FLAG = 'B') BCNT FROM BNTBUYERGROUP A WHERE GROUP_FLAG = 'A'
AND GROUP_NAME LIKE '%' || #{st_group_name} || '%'
ORDER BY SORT_SEQ, GROUP_CODE

